51	/** Compile and check an expression. `cached: false` gives a private instance (for `$eval`). */
52	function compile(expression: string, cached = true): Compiled {
53	  const hit = cached ? cache.get(expression) : undefined;
54	  if (hit) return hit;
55	  let compiled: Compiled;
56	  try {
57	    compiled = jsonata(expression);
58	  } catch (error) {
59	    throw new ExpressionError(`expression failed to compile: ${describeError(error)}`, {
60	      expression,
61	    });
62	  }
63	  const unsafe = unsafeRegexIn(compiled.ast());
64	  if (unsafe) {
65	    throw new ExpressionError(
66	      `expression uses the regular expression /${unsafe.source}/, which can run without bound: ${unsafe.reason}`,
67	      { expression },
68	    );
69	  }
70	  if (!cached) return compiled;
71	  if (cache.size >= CACHE_LIMIT) {
72	    const first = cache.keys().next().value;
73	    if (first !== undefined) cache.delete(first);
74	  }
75	  cache.set(expression, compiled);
76	  return compiled;
77	}
