102	      return await builtin.implementation.apply(this, [source, focus]);
103	    } catch (error) {
104	      // JSONata's $eval wraps a failure in a new error that embeds the inner message; nested
105	      // evals would grow it exponentially. Normalise at every boundary: keep the innermost
106	      // cause, and bound the message.
107	      throw normaliseEvalError(error);
108	    }
