123	  let cause = error;
124	  while (
125	    !(cause instanceof ExpressionError) &&
126	    typeof cause === 'object' &&
127	    cause !== null &&
128	    'error' in cause &&
129	    cause.error !== undefined
130	  ) {
131	    cause = cause.error;
132	  }
133	  if (cause instanceof ExpressionError) return cause;
134	  return new ExpressionError(`$eval failed: ${bounded(describeError(cause))}`);
135	}
