138	  expr: Compiled,
139	  expression: string,
140	  input: unknown,
141	  options: ExpressionOptions,
142	): Promise<unknown> {
143	  try {
144	    const result: unknown = await expr.evaluate(input, {
145	      ...options.bindings,
146	      eval: CHECKED_EVAL,
147	      ...evaluationHooks(options.timeoutMs ?? 2000, options.maxDepth ?? 200),
148	    });
149	    return result;
150	  } catch (error) {
151	    if (error instanceof ExpressionError) throw error;
152	    throw new ExpressionError(`expression failed: ${bounded(describeError(error))}`, {
153	      expression,
154	    });
155	  }
156	}
