160	 * The pinned JSONata patch binds the hooks in that invocation's frame and finishes
161	 * sibling evaluations before starting the next.
162	 */
163	const ENTRY_HOOK = Symbol.for('jsonata.__evaluate_entry');
164	const EXIT_HOOK = Symbol.for('jsonata.__evaluate_exit');
165	
166	function evaluationHooks(timeoutMs: number, maxDepth: number): Record<symbol, () => void> {
167	  let depth = 0;
168	  const start = Date.now();
169	  const check = (): void => {
170	    if (depth > maxDepth) {
171	      throw new ExpressionError(`expression exceeded max depth ${maxDepth}`);
172	    }
173	    if (Date.now() - start > timeoutMs) {
174	      throw new ExpressionError(`expression exceeded ${timeoutMs}ms`);
175	    }
176	  };
177	  return {
178	    [ENTRY_HOOK]: () => {
179	      depth += 1;
180	      check();
181	    },
182	    [EXIT_HOOK]: () => {
183	      depth -= 1;
184	      check();
185	    },
186	  };
187	}
