189	/** Evaluate a JSONata expression against an input. Undefined results become `undefined`. */
190	export async function evaluateExpression(
191	  expression: string,
192	  input: unknown,
193	  options: ExpressionOptions = {},
194	): Promise<unknown> {
195	  return run(compile(expression), expression, input, options);
196	}
197	
198	/** Predicate coercion: missing/null are false, nonempty collections pass, scalars use Boolean. */
199	export async function evaluatePredicate(
200	  expression: string,
201	  input: unknown,
202	  options: ExpressionOptions = {},
203	): Promise<boolean> {
204	  const value = await evaluateExpression(expression, input, options);
205	  if (value === undefined || value === null) return false;
206	  if (Array.isArray(value)) return value.length > 0;
207	  if (typeof value === 'object') return Object.keys(value).length > 0;
208	  return Boolean(value);
209	}
