212	export function checkExpression(expression: string): string | null {
213	  try {
214	    compile(expression);
215	    return null;
216	  } catch (error) {
217	    return error instanceof Error ? error.message : String(error);
218	  }
219	}
220	
221	/** The same parsed and safety-checked syntax used for evaluation. Inspect without modifying it. */
222	export function expressionAst(source: string): unknown {
223	  return compile(source).ast();
224	}
