347	      errors: validation.errors,
348	    });
349	  }
350	  const exists = getAtPointer(thread, request.target).found;
351	  const patch: JsonPatch = [
352	    { op: exists ? 'replace' : 'add', path: request.target, value: repaired },
353	  ];
354	  return { thread: applyPatch(thread, patch), patch };
