322	    if (Array.isArray(current)) {
323	      const i = Number(token);
324	      if (!Number.isInteger(i) || i >= current.length) return false;
325	      current = current[i];
326	    } else if (current && typeof current === 'object') {
327	      if (!Object.prototype.hasOwnProperty.call(current, token)) return false;
328	      current = (current as Record<string, unknown>)[token];
329	    } else {
330	      return false;
331	    }
332	  }
333	  return true;
