1	import { LoopDefinitionSchema } from '@graphgoblin/contracts';
2	import { stableStringify } from '@graphgoblin/domain';
3	import type { RunRecord, RunRecovery, RecoveryAction } from '@graphgoblin/contracts';
4	import type { EnginePorts, RecoveryFacts } from './ports.js';
5	import { childSessionRecovered } from './session-recovery.js';
6	import { definitionUpgradeRequired } from './stored-definition.js';
7	
8	const allowed: RecoveryAction = { allowed: true };
9	export const refused = (
10	  code: Exclude<RecoveryAction, { allowed: true }>['code'],
11	  message: string,
12	): Exclude<RecoveryAction, { allowed: true }> => ({ allowed: false, code, message });
13	
14	/** Main's execution rules, exposed without advancing or repairing execution. */
15	export async function runRecovery(
16	  ports: EnginePorts,
17	  run: RunRecord,
18	  facts: RecoveryFacts,
19	  owningParent?: string,
20	): Promise<RunRecovery> {
21	  const { observedSeq } = facts;
22	  const version = await ports.loops.getVersion(run.versionId);
23	  const parsed = version ? LoopDefinitionSchema.safeParse(version.definition) : undefined;
24	  const definition = parsed?.success ? parsed.data : undefined;
25	  const initial = await ports.runs.getInitialThread(run.id);
26	  let common: RecoveryAction | undefined;
27	  if (!version || !definition || definitionUpgradeRequired(version))
28	    common = refused(
29	      'DEFINITION_UNAVAILABLE',
30	      'The pinned definition is unavailable or cannot execute.',
31	    );
32	  else if (
33	    !initial ||
34	    (run.currentNodeId && !definition.nodes.some((node) => node.id === run.currentNodeId))
35	  )
36	    common = refused(
37	      'STATE_UNAVAILABLE',
38	      'The recorded starting state or current node is unavailable.',
39	    );
40	
41	  // Appending a lifecycle event and projecting its status are separate durable operations.
42	  // An equal tail sequence does not prove that the projection includes the failure payload.
43	  // Preserve the readable record, but authorize neither recovery action during that gap.
44	  const lifecycle = facts.lifecycle;
45	  if (
46	    !common &&
47	    ((lifecycle?.type === 'run.failed' &&
48	      (run.status !== 'failed' ||
49	        stableStringify(run.failure ?? null) !== stableStringify(lifecycle.failure))) ||
50	      (lifecycle?.type === 'run.finished' && run.status !== lifecycle.status) ||
51	      (lifecycle?.type === 'run.cancelled' && run.status !== 'cancelled') ||
52	      (lifecycle?.type === 'run.resumed' && run.status === 'paused') ||
53	      ((lifecycle?.type === 'run.started' || lifecycle?.type === 'run.resumed') &&
54	        ['failed', 'succeeded', 'exhausted', 'cancelled'].includes(run.status)))
55	  )
56	    common = refused(
57	      'RECOVERY_STALE',
58	      'The recorded lifecycle and run status are still being synchronized. Refresh and review its current recovery choices.',
59	    );
60	
61	  if (!common && run.parentRunId && owningParent !== run.parentRunId) {
62	    const parent = await ports.runs.get(run.parentRunId);
63	    const details = parent?.failure?.details;
64	    const child =
65	      typeof details === 'object' && details !== null && !Array.isArray(details)
66	        ? details.childRunId
67	        : undefined;
68	    const pending =
69	      parent &&
70	      ['queued', 'running', 'waiting', 'paused'].includes(parent.status) &&
71	      (['queued', 'running', 'waiting', 'paused'].includes(run.status) ||
72	        (run.status === 'failed' && run.failure !== undefined))
73	        ? (await ports.events.recoveryFacts(parent.id, [])).resumed?.childRecovery
74	        : undefined;
75	    if ((parent?.status === 'failed' && child === run.id) || pending?.runId === run.id)
76	      common = {
77	        ...refused(
78	          'PARENT_RECOVERY_REQUIRED',
79	          `Recovery belongs to parent run ${run.parentRunId}. Open that parent to review its recovery choices.`,
80	        ),
81	        parentRunId: run.parentRunId,
82	      };
83	  }
84	
85	  const uncertain =
86	    run.status === 'failed' &&
87	    (run.failure?.code === 'SCRIPT_OUTCOME_UNCERTAIN' ||
88	      run.failure?.script?.state === 'outcome-uncertain');
89	  const uncertainNode = run.failure?.nodeId ?? run.currentNodeId;
90	  const missing =
91	    run.status === 'failed' &&
92	    run.failure?.code === 'HARNESS_SESSION_MISSING' &&
93	    !(await childSessionRecovered(ports, run));
94	  const active =
95	    ['queued', 'running', 'waiting'].includes(run.status) ||
96	    (run.status === 'failed' && facts.lifecycle?.type === 'run.resumed');
97	  const resume =
98	    common ??
99	    (run.cancelRequestedAt || run.status === 'cancelled'
100	      ? refused('RUN_CANCELLED', 'This run was cancelled; Resume is unavailable.')
101	      : active
102	        ? refused('RUN_ACTIVE', 'This run is still active. Pause it before continuing with Resume.')
103	        : missing
104	          ? refused(
105	              'SESSION_RECOVERY_REQUIRED',
106	              'Choose Start fresh session on the failed inference run before resuming, or use Replay for a deliberate new run.',
107	            )
108	          : run.status === 'paused'
109	            ? allowed
110	            : run.status === 'failed' &&
111	                (run.failure?.resumable || run.failure?.code === 'HARNESS_SESSION_MISSING')
112	              ? uncertain
113	                ? refused(
114	                    'SCRIPT_CONSENT_REQUIRED',
115	                    'The script may already have produced its effect. Choose Recover script to explicitly retry.',
116	                  )
117	                : allowed
118	              : run.status === 'failed'
119	                ? refused(
120	                    'FAILURE_NOT_RESUMABLE',
121	                    'This failure cannot be resumed. Inspect its cause or choose a reached Replay node for a new run.',
122	                  )
123	                : refused(
124	                    'RUN_FINISHED',
125	                    'This run has finished. Resume only continues paused runs or supported failures.',
126	                  ));
127	  const nodes = await Promise.all(
128	    (definition?.nodes ?? []).map(async (node) => {
129	      const reachable = new Set([node.id]);
130	      const pending = [node.id];
131	      for (const id of pending)
132	        for (const edge of definition?.edges ?? [])
133	          if (edge.from.node === id && !reachable.has(edge.to.node)) {
134	            reachable.add(edge.to.node);
135	            pending.push(edge.to.node);
136	          }
137	      const effects: RunRecovery['replay'][number]['effects'] = [];
138	      for (const target of definition?.nodes ?? []) {
139	        if (!reachable.has(target.id)) continue;
140	        if (target.kind === 'script' || target.kind === 'inference' || target.kind === 'subloop')
141	          effects.push({ nodeId: target.id, label: target.label, kind: target.kind });
142	        else if (
143	          target.kind === 'exit' &&
144	          target.config.returns !== 'none' &&
145	          target.config.destinations.length
146	        )
147	          effects.push({ nodeId: target.id, label: target.label, kind: 'delivery' });
148	      }
149	      let action = common;
150	      if (!action && !facts.reachedNodeIds.includes(node.id))
