1	import type { RunErrorCode, RunFailure, RecoveryRefusalCode } from '@graphgoblin/contracts';
2	import type { EventDraft } from './ports.js';
3	
4	/** Artifact I/O failed explicitly; missing content is represented separately by undefined. */
5	export class ArtifactStoreError extends Error {
6	  constructor(
7	    readonly code: 'ARTIFACT_CORRUPT' | 'ARTIFACT_WRITE_FAILED',
8	    readonly ref: string,
9	    options?: ErrorOptions,
10	  ) {
11	    super(
12	      code === 'ARTIFACT_CORRUPT'
13	        ? 'Artifact content does not match its reference'
14	        : 'Artifact could not be published',
15	      options,
16	    );
17	    this.name = 'ArtifactStoreError';
18	  }
19	}
20	
21	/** Safe, transport-independent failure: an HTTP probe body exceeded its byte budget. */
22	export class ProbeBodyOverflowError extends Error {
23	  readonly code = 'HTTP_PROBE_BODY_OVERFLOW';
24	  constructor() {
25	    super('HTTP probe body exceeds byte limit');
26	    this.name = 'ProbeBodyOverflowError';
27	  }
28	}
29	
30	/**
31	 * Thrown by handlers and the executor for the "unavoidable" failure class in the resiliency
32	 * model (docs/05-execution-engine.md). Everything else that escapes a handler is a bug and is
33	 * recorded as INTERNAL_ERROR.
34	 */
35	export class RunFailureError extends Error {
36	  constructor(
37	    readonly code: RunErrorCode,
38	    message: string,
39	    readonly options: {
40	      resumable?: boolean;
41	      details?: unknown;
42	      nodeId?: string;
43	      script?: RunFailure['script'];
44	      inference?: RunFailure['inference'];
45	      missingSession?: RunFailure['missingSession'];
46	      /** Facts the failing visit learned, appended in the same write as `run.failed` (#398). */
47	      records?: EventDraft[];
48	    } = {},
49	  ) {
50	    super(message);
51	    this.name = 'RunFailureError';
52	  }
53	
54	  toFailure(nodeId?: string): RunFailure {
55	    const id = this.options.nodeId ?? nodeId;
56	    return {
57	      code: this.code,
58	      message: this.message,
59	      resumable: this.options.resumable ?? true,
60	      ...(id ? { nodeId: id } : {}),
61	      ...(this.options.script ? { script: this.options.script } : {}),
62	      ...(this.options.inference ? { inference: this.options.inference } : {}),
63	      ...(this.options.missingSession ? { missingSession: this.options.missingSession } : {}),
64	      ...(this.options.details !== undefined
65	        ? { details: toJsonDetails(this.options.details) }
66	        : {}),
67	    };
68	  }
69	}
70	
71	/**
72	 * A stored definition the current contract refuses: an exit that publishes an Event, retired by
73	 * ADR-0044 but still present in a version, draft or draft-run snapshot saved before. Thrown
74	 * before the definition is served or executed. As a run failure it is not resumable: the pinned
75	 * definition never changes, so resuming cannot help.
76	 */
77	export class LoopUpgradeRequiredError extends RunFailureError {
78	  constructor(
79	    readonly loopId: string,
80	    readonly versionId: string,
81	    readonly version: number,
82	    readonly paths: string[],
83	    message: string,
84	  ) {
85	    super('LOOP_UPGRADE_REQUIRED', message, {
86	      resumable: false,
87	      details: { loopId, versionId, version, paths },
88	    });
89	    this.name = 'LoopUpgradeRequiredError';
90	  }
91	}
92	
93	/** Thrown when a handler observes its abort signal. */
94	export class RunCancelledError extends Error {
95	  constructor() {
96	    super('run cancelled');
97	    this.name = 'RunCancelledError';
98	  }
99	}
100	
101	/**
102	 * Thrown by the subloop handler when the child it awaits was cancelled. The run is cancelled in
103	 * turn, at the child's request, as cancelling inline work cancels the run that does it (#251).
104	 */
105	export class ChildCancelledError extends Error {
106	  /** `records` are appended in the same write as the cancellation request (#398). */
107	  constructor(
108	    readonly childRunId: string,
109	    readonly records: EventDraft[] = [],
110	  ) {
111	    super(`subloop child ${childRunId} was cancelled`);
112	    this.name = 'ChildCancelledError';
113	  }
114	}
115	
116	function toJsonDetails(details: unknown): RunFailure['details'] {
117	  try {
118	    return JSON.parse(JSON.stringify(details)) as RunFailure['details'];
119	  } catch {
120	    return String(details);
121	  }
122	}
123	
124	export function isAbortError(error: unknown): boolean {
125	  return (
126	    error instanceof RunCancelledError ||
127	    (error instanceof Error && (error.name === 'AbortError' || error.message === 'run cancelled'))
128	  );
129	}
130	
131	export function describeError(error: unknown): string {
132	  if (error instanceof Error) return error.message;
133	  if (typeof error === 'object' && error !== null && 'message' in error) {
134	    return String(error.message);
135	  }
136	  return String(error);
137	}
138	
139	/**
