1	/**
2	 * Locate typed authored sources without parsing or materializing defaults in the draft.
3	 * Metadata copies retain their marker's identity through sameSchema.
4	 */
5	import {
6	  ExpressionSchema,
7	  JsonPointerSchema,
8	  LoopSettingsSchema,
9	  NodeConfigSchemas,
10	  TemplateSchema,
11	  sameSchema,
12	  type NodeKind,
13	} from '@graphgoblin/contracts';
14	import { sourceAnalysis, type SourceKind } from './source-analysis.js';
15	
16	interface SyntaxIssue {
17	  code: 'TEMPLATE_INVALID' | 'EXPRESSION_INVALID';
18	  severity: 'error';
19	  message: string;
20	  nodeId?: string;
21	  /** The field: config.<path> in the node, or settings.<path> in the loop's settings. */
22	  path: string;
23	}
24	
25	/** The slice of a Zod 4 schema this walker reads. */
26	interface SchemaLike {
27	  _zod: { def: Record<string, unknown> & { type: string } };
28	  safeParse(value: unknown): { success: boolean };
29	}
30	
31	type Found = { kind: SourceKind; source: string; path: string };
32	type AuthoredField = { kind: SourceKind | 'pointer'; source: string; segments: string[] };
33	interface SourceSchemas {
34	  template: unknown;
35	  expression: unknown;
36	  pointer?: unknown;
37	}
38	const currentSources = { template: TemplateSchema, expression: ExpressionSchema };
39	
40	const WRAPPERS = new Set([
41	  'optional',
42	  'nullable',
43	  'default',
44	  'prefault',
45	  'nonoptional',
46	  'readonly',
47	  'catch',
48	]);
49	
50	function walk(
51	  schema: SchemaLike,
52	  value: unknown,
53	  segments: string[],
54	  found: AuthoredField[],
55	  markers: SourceSchemas,
56	): void {
57	  if (value === undefined || value === null) return;
58	  const kind = sameSchema(schema, markers.template as SchemaLike)
59	    ? 'template'
60	    : sameSchema(schema, markers.expression as SchemaLike)
61	      ? 'expression'
62	      : markers.pointer && sameSchema(schema, markers.pointer as SchemaLike)
63	        ? 'pointer'
64	        : undefined;
65	  if (kind) {
66	    if (typeof value === 'string') found.push({ kind, source: value, segments });
67	    return;
68	  }
69	  const def = schema._zod.def;
70	  if (WRAPPERS.has(def.type)) {
71	    walk(def['innerType'] as SchemaLike, value, segments, found, markers);
72	  } else if (def.type === 'object' && typeof value === 'object') {
73	    const shape = def['shape'] as Record<string, SchemaLike>;
74	    for (const [key, child] of Object.entries(shape)) {
75	      walk(child, (value as Record<string, unknown>)[key], [...segments, key], found, markers);
76	    }
77	  } else if (def.type === 'array' && Array.isArray(value)) {
78	    value.forEach((item, index) =>
79	      walk(def['element'] as SchemaLike, item, [...segments, String(index)], found, markers),
80	    );
81	  } else if (def.type === 'record' && typeof value === 'object') {
82	    for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
83	      walk(def['valueType'] as SchemaLike, item, [...segments, key], found, markers);
84	    }
85	  } else if (def.type === 'union') {
86	    const options = def['options'] as SchemaLike[];
87	    const discriminator = def['discriminator'];
88	    let option: SchemaLike | undefined;
89	    if (markers.pointer && typeof discriminator === 'string' && typeof value === 'object') {
90	      // The rename works on editor input, where another field in a discriminated
91	      // branch may be temporarily invalid. Its literal discriminator still selects
92	      // one unambiguous branch without materializing defaults or hiding typed sources.
93	      const discriminant = (value as Record<string, unknown>)[discriminator];
94	      option = options.find((candidate) => {
95	        const shape = candidate._zod.def['shape'] as Record<string, SchemaLike> | undefined;
96	        return shape?.[discriminator]?.safeParse(discriminant).success === true;
97	      });
98	    } else {
99	      option = options.find((candidate) => candidate.safeParse(value).success);
100	    }
101	    if (option) walk(option, value, segments, found, markers);
102	  }
103	}
104	
105	/** Every template and expression in value as described by schema, with its dotted path. */
106	export function findAuthoredSources(
107	  schema: unknown,
108	  value: unknown,
109	  markers: SourceSchemas = currentSources,
110	): Found[] {
111	  return authoredFields(schema, value, markers).flatMap(({ kind, source, segments }) =>
112	    kind === 'pointer' ? [] : [{ kind, source, path: segments.join('.') }],
113	  );
114	}
115	
